  left: 0;
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

main {
  max-width: 720px;
  margin: 0 auto;
  padding: 32px 20px 64px;
}

.quiz-header {
  margin-bottom: 24px;
}

h1 {
  margin: 0 0 8px;
  font-size: 1.75rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.lede {
  margin: 0;
  color: var(--text-muted);
}

.instructions {
  margin: 0 0 16px;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.instructions span[aria-hidden] {
  color: var(--danger);
  font-weight: 700;
}

.form-field {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 18px;
  overflow: hidden;
}

.form-field fieldset {
  border: 0;
  padding: 18px 20px;
  margin: 0;
}

.form-field legend {
  font-weight: 600;
  font-size: 1.05rem;
  padding: 0;
  margin-bottom: 6px;
  color: var(--text);
}

.required-indicator {
  color: var(--danger);
  margin-left: 2px;
  font-weight: 700;
}

.help-text {
  margin: 4px 0 12px;
  color: var(--text-muted);
  font-size: 0.875rem;
  font-style: italic;
}

.options {
  display: grid;
  gap: 8px;
  margin-top: 8px;
}

.option {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 6px;
  cursor: pointer;
  transition: border-color 0.15s, background-color 0.15s;
}

.option:hover {
  border-color: var(--border-strong);
  background: #11161d;
}

.option:has(input:checked) {
  border-color: var(--accent);
  background: rgba(79, 140, 255, 0.08);
}

.option input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border: 1.5px solid var(--border-strong);
  border-radius: 4px;
  background: var(--bg);
  cursor: pointer;
  display: inline-grid;
  place-content: center;
  flex-shrink: 0;
  margin: 0;
}

.option input[type="checkbox"]::before {
  content: "";
  width: 10px;
  height: 10px;
  transform: scale(0);
  transition: transform 0.1s;
  background: var(--accent-contrast);
  clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
}

.option input[type="checkbox"]:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.option input[type="checkbox"]:checked::before {
  transform: scale(1);
}

.option input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.option span {
  user-select: none;
}

.error-text {
  color: var(--danger);
  font-size: 0.875rem;
  margin: 12px 0 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.error-text::before {
  content: "⚠";
  font-size: 1rem;
}

.form-field.has-error {
  border-color: var(--danger);
}

.actions {
  margin-top: 24px;
}

.submit-btn {
  background: var(--accent);
  color: var(--accent-contrast);
  border: 1px solid var(--accent);
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.15s, border-color 0.15s;
}

.submit-btn:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.submit-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.submit-btn:active {
  transform: translateY(1px);
}

.result {
  margin-top: 20px;
  padding: 0;
}

.result.show {
  padding: 16px 20px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.result h2 {
  margin: 0 0 8px;
  font-size: 1.1rem;
}

.result ul {
  margin: 8px 0 0;
  padding-left: 20px;
}

.result .score {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--success);
}

@media (forced-colors: active) {
  .form-field,
  .option,
  .submit-btn,
  .result.show {
    border: 1px solid ButtonBorder;
  }
  .option input[type="checkbox"] {
    border: 1.5px solid ButtonBorder;
    background: Canvas;
  }
  .option input[type="checkbox"]:checked {
    background: Highlight;
    border-color: Highlight;
  }
  .option input[type="checkbox"]::before {
    background: HighlightText;
  }
  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
  }
  .skip-link {
    background: Highlight;
    color: HighlightText;
  }
}

@media (max-width: 480px) {
  main { padding: 20px 14px 48px; }
  h1 { font-size: 1.4rem; }
  .form-field fieldset { padding: 14px 14px; }
}
