AssistantMessageToolRequest(name='create', tool_call_id='toolu_017fPGoRCr1eEhBgEip5WkGA', arguments={'file_text': '(function () {
  'use strict';

  const ANSWERS = {
    q1: ['java', 'rust'],
    q2: ['javascript', 'typescript', 'webassembly'],
    q3: ['haskell', 'elixir', 'clojure']
  };

  const form = document.getElementById('quiz-form');
  const result = document.getElementById('result');

  function getSelected(name) {
    return Array.from(
      form.querySelectorAll('input[name="' + name + '"]:checked')
    ).map((el) => el.value);
  }

  function setFieldError(name, message) {
    const errorEl = document.getElementById(name + '-error');
    const field = errorEl.closest('.form-field');
    const inputs = form.querySelectorAll('input[name="' + name + '"]');
    if (message) {
      errorEl.textContent = message;
      errorEl.hidden = false;
      field.classList.add('has-error');
      inputs.forEach((i) => i.setAttribute('aria-invalid', 'true'));
    } else {
      errorEl.textContent = '';
      errorEl.hidden = true;
      field.classList.remove('has-error');
      inputs.forEach((i) => i.removeAttribute('aria-invalid'));
    }
  }

  function arraysEqualAsSets(a, b) {
    if (a.length !== b.length) return false;
    const set = new Set(a);
    return b.every((v) => set.has(v));
  }

  form.addEventListener('change', (e) => {
    const name = e.target.name;
    if (name && getSelected(name).length > 0) {
      setFieldError(name, '');
    }
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    const questions = ['q1', 'q2', 'q3'];
    let firstInvalid = null;

    questions.forEach((name) => {
      const selected = getSelected(name);
      if (selected.length === 0) {
        setFieldError(name, 'Please select at least one answer.');
        if (!firstInvalid) firstInvalid = name;
      } else {
        setFieldError(name, '');
      }
    });

    if (firstInvalid) {
      const firstInput = form.querySelector('input[name="' + firstInvalid + '"]');
      if (firstInput) firstInput.focus();
      result.className = 'result';
      result.innerHTML = '';
      return;
    }

    let correctCount = 0;
    const breakdown = questions.map((name, idx) => {
      const selected = getSelected(name);
      const correct = ANSWERS[name];
      const isCorrect = arraysEqualAsSets(selected, correct);
      if (isCorrect) correctCount++;
      return {
        n: idx + 1,
        isCorrect,
        correct
      };
    });

    const list = breakdown
      .map((b) => {
        const status = b.isCorrect ? '✓ Correct' : '✗ Incorrect';
        return (
          '<li>Question ' +
          b.n +
          ': <strong>' +
          status +
          '</strong>' +
          (b.isCorrect
            ? ''
            : ' — answers: ' + b.correct.join(', ')) +
          '</li>'
        );
      })
      .join('');

    result.className = 'result show';
    result.innerHTML =
      '<h2>Results</h2>' +
      '<p class="score">' +
      correctCount +
      ' / ' +
      questions.length +
      ' correct</p>' +
      '<ul>' +
      list +
      '</ul>';
    result.focus?.();
  });
})();
